const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let ptr = 0;
const N = data[ptr++];
const K = data[ptr++];
const T = data[ptr++];

const P = new Int32Array(N);
for (let i = 0; i < N; i++) P[i] = data[ptr++];

const a = [];
for (let i = 0; i < N; i++) {
  const g = data[ptr++];
  if (g === 1) a.push(i + 1);
}

if (T >= K * N) {
  const sorted = Array.from(P).sort((x, y) => y - x);
  let sum = 0;
  for (let i = 0; i < K; i++) sum += sorted[i];
  console.log(sum);
  return;
}

const Vstride = 9 * K + 1;
const size = N * Vstride;
const INF = 1000000005;

let prev = new Int32Array(size);
prev.fill(INF);

const a0 = a[0];
for (let i = 0; i < N; i++) {
  const pos = i + 1;
  const val = P[i];
  const cost = a0 > pos ? a0 - pos : pos - a0;
  prev[i * Vstride + val] = cost;
}

let cur = new Int32Array(size);
cur.fill(INF);
const prefix = new Int32Array(Vstride);

for (let j = 2; j <= K; j++) {
  prefix.fill(INF);
  const maxPrevVal = 9 * (j - 1);
  const aj = a[j - 1];

  for (let i = 0; i < N; i++) {
    const pos = i + 1;
    const base = aj > pos ? aj - pos : pos - aj;
    const val = P[i];
    const row = i * Vstride;
    let curIdx = row + val;
    let prevIdx = row;

    for (let w = 0; w <= maxPrevVal; w++) {
      const pc = prefix[w];
      cur[curIdx] = pc + base;
      const pv = prev[prevIdx];
      if (pv < pc) prefix[w] = pv;
      curIdx++;
      prevIdx++;
    }
  }

  let tmp = prev;
  prev = cur;
  cur = tmp;
}

const maxVal = 9 * K;
const minCost = new Int32Array(Vstride);
minCost.fill(INF);

for (let i = 0; i < N; i++) {
  const row = i * Vstride;
  for (let v = 0; v <= maxVal; v++) {
    const c = prev[row + v];
    if (c < minCost[v]) minCost[v] = c;
  }
}

let ans = 0;
for (let v = maxVal; v >= 0; v--) {
  if (minCost[v] <= T) {
    ans = v;
    break;
  }
}

console.log(ans);
